template.script:
            (function () {
                function loadBestSellers() {
                    fetch('/sweet/best-sellers', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { limit: 8 } }),
                    })
                    .then(function (r) { return r.json(); })
                    .then(function (data) {
                        var products = data.result || [];
                        var grid = document.getElementById('sc-best-sellers-grid');
                        if (!grid) return;
                        grid.innerHTML = '';
                        if (!products.length) {
                            grid.innerHTML = '
Próximamente disponible';
                            return;
                        }
                        products.forEach(function (p) {
                            var badge = p.available
                                ? 'Disponible'
                                : 'Sin stock';
                            var card = '
' +
                                '
' +
                                badge +
                                '' +
                                '
' +
                                '
' + p.name + '' +
                                '
' + p.price.toFixed(2) + ' CUP' +
                                '★ ' + Math.round(p.qty_sold) + ' vendidos' +
                                '';
                            grid.innerHTML += card;
                        });
                    })
                    .catch(function () {
                        // Silently fail — skeleton cards remain
                    });
                }

                if (document.readyState === 'loading') {
                    document.addEventListener('DOMContentLoaded', loadBestSellers);
                } else {
                    loadBestSellers();
                }
            })();
